def fib(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 0
    if n == 1:
        return 1

    a = 0
    b = 1
    for _ in range(2, n + 1):
        next_fib = a + b
        a = b
        b = next_fib
    return b
```

