class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def preorderTraversal(root: TreeNode) -> list[int]:
    result = []
    if not root:
        return result

    stack = [root]

    while stack:
        node = stack.pop()
        result.append(node.val)

        # Push right child first so that left child is processed before right child (LIFO)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)

    return result
```

