class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def preorderTraversal(root: TreeNode) -> list[int]:
    result = []
    stack = []
    current = root

    while current or stack:
        if current:
            result.append(current.val)
