class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def postorderTraversal(root: TreeNode) -> list[int]:
    result = []
    if root:
        stack = [root]
        while stack:
            node = stack.pop()
            result.append(node.val)

            # For postorder (Left -> Right -> Root), we push Right then Left
            # so that Left is processed before Right when popping.
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)

    # The iterative approach above results in Root -> Right -> Left order (preorder modification).
    # Let's use a standard recursive approach for clarity of postorder.

    def traverse(node):
        if node:
            traverse(node.left)
            traverse(node.right)
            result.append(node.val)

    result = []
    traverse(root)
    return result
```

