def dfs(graph, start):
    visited = set()
    order = []
    stack = [start]

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            order.append(node)
            # Push neighbors onto the stack in reverse order to maintain typical DFS order
            # (i.e., process neighbors in the order they appear in the adjacency list)
            if node in graph:
                neighbors = graph[node]
                for neighbor in reversed(neighbors):
                    if neighbor not in visited:
                        stack.append(neighbor)
    return order
```

